#!/usr/bin/env bash
set -euo pipefail

if [[ $# -lt 2 || $# -gt 3 ]]; then
  echo "usage: $0 BASELINE_ARTIFACT_ROOT DOWNSTREAM_ARTIFACT_ROOT [GPU_IDS]" >&2
  exit 2
fi

baseline_root=$1
downstream_root=$2
gpu_ids=${3:-0,1,2,3,4,5}

# Fixed banks are independently regenerated by parent and worker processes.
# Pin every common CPU numerical backend before Python imports NumPy so the
# archived bank and worker audit use the same BLAS reduction order.
export OPENBLAS_NUM_THREADS=1
export OMP_NUM_THREADS=1
export MKL_NUM_THREADS=1
export NUMEXPR_NUM_THREADS=1
export VECLIB_MAXIMUM_THREADS=1

if [[ -e "$baseline_root" && ! -d "$baseline_root" ]]; then
  echo "baseline artifact root exists but is not a directory: $baseline_root" >&2
  exit 2
fi
if [[ -e "$downstream_root" && ! -d "$downstream_root" ]]; then
  echo "downstream artifact root exists but is not a directory: $downstream_root" >&2
  exit 2
fi

repo_root=$(git rev-parse --show-toplevel)
cd "$repo_root"

echo "pipeline_start_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
echo "code_commit=$(git rev-parse HEAD)"
echo "baseline_root=$baseline_root"
echo "downstream_root=$downstream_root"
echo "gpu_ids=$gpu_ids"
python --version
nvidia-smi --query-gpu=index,name,driver_version,memory.total --format=csv,noheader

python -m repro.sagodi_protocol.source_repaired_baselines_v6 \
  --stage smoke --artifact-root "$baseline_root" --gpus cpu
python -m repro.sagodi_protocol.source_repaired_baselines_v6 \
  --stage sentinel --artifact-root "$baseline_root" --gpus "$gpu_ids"
python -m repro.sagodi_protocol.source_repaired_baselines_v6 \
  --stage fanout --artifact-root "$baseline_root" --gpus "$gpu_ids"
python -m repro.sagodi_protocol.source_repaired_baselines_v6 \
  --stage main --artifact-root "$baseline_root" --gpus "$gpu_ids"

python -m repro.sagodi_protocol.source_repaired_lru_calru_v6 \
  --stage smoke --baseline-root "$baseline_root" \
  --artifact-root "$downstream_root" --gpus cpu

for stage in lru_sentinel lru_fanout lru_main \
             no_rp_sentinel no_rp_fanout no_rp_main \
             ca_rp_sentinel ca_rp_fanout ca_rp_main; do
  python -m repro.sagodi_protocol.source_repaired_lru_calru_v6 \
    --stage "$stage" --baseline-root "$baseline_root" \
    --artifact-root "$downstream_root" --gpus "$gpu_ids"
done

echo "pipeline_complete_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
